contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user) public {
        // Only msg.sender is authorized initially (it deployed c).
        // Make the caller an authorized ward first, so rely(user) can succeed for any user.
        if (caller != address(this)) {
            c.rely(caller);
        }

        // The deciding call: rely(user) must succeed for an authorized caller.
        bool reverted;
        try c.rely(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the rely call did not revert, then wards[user] == 1.
        // Otherwise the state was not changed by rely (wards[user] stays 0 unless it was already 1).
        uint256 wardsUser = c.wards(user);
        assert((!reverted && wardsUser == 1) || (reverted && wardsUser != 0));
    }
}

contract InvMutTest {
