        // The deciding call: rely(user) must succeed because msg.sender is a ward.
        c.rely(user);

        // After a successful rely, the public wards mapping must record user as a ward (1).
        uint256 wardsUser = c.wards(user);
        assert(wardsUser == 1);
    }
}

