contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user) public payable {
        require(caller != address(0), "invalid caller");
        require(user != address(0), "invalid user");

        // Setup: give the test contract authorization so state-changing calls can proceed.
        c.rely(address(this));

        uint256 callerWardBefore = c.wards(caller);
        uint256 userWardBefore = c.wards(user);

        bool reverted;
        try c.deny(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call either reverts (in which case the ward of the target is unchanged)
        // or completes, in which case wards[user] is exactly 0, independently of prior state.
        assert(
            reverted
                ? c.wards(user) == userWardBefore
                : c.wards(user) == 0
        );
    }

    receive() external payable {}
}

