contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 newPrice, bool callerAuthorized) public payable {
        // Setup: make the test contract act as a ward via c's public rely, but only
        // so we can construct the authorized-call scenario.  However, since the
        // deployed C already has wards[this] = 1 if this contract deployed it, we
        // must instead simulate the unauthorized scenario by attempting the call
        // directly with this same address.  To deterministically cover both cases
        // we can first deny ourselves if needed, then rely ourselves again.
        // Because msg.sender on c is always this contract, the only way to change
        // authorization from this contract's perspective is to rely/deny itself.

        // If we want an unauthorized call, we deny ourselves first (only possible
        // because this contract is ward at deployment).  If we want an authorized
        // call, we rely ourselves first (idempotent).
        if (callerAuthorized) {
            c.rely(address(this));
        } else {
            c.deny(address(this));
        }

        uint128 oldPrice = c.latestPrice();

        bool reverted;
        try c.updatePrice(newPrice) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 currentPrice = c.latestPrice();

        // General rule: the call reverts iff the caller is not authorized, and
        // when it succeeds the price is exactly the new value; when it reverts
        // the price is unchanged.
        if (callerAuthorized) {
            assert(!reverted && currentPrice == newPrice);
        } else {
            assert(reverted && currentPrice == oldPrice);
        }
    }

    receive() external payable {}
}

