contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 /*unused args but required to be general*/) public payable {
        // totalSupply() is a view function taking no arguments; we call it on c
        // and require it to match the share contract's totalSupply().
        uint256 supplyFromPool = c.totalSupply();

        // The share token is reachable through c.share(), which is a public immutable getter.
        // We must not assume its interface name; use the low-level call via c itself is not allowed.
        // However, we can rely on the fact that if totalSupply() completes, it must equal the share token's supply.
        // Since we cannot directly call share.totalSupply() without declaring the interface, we can still
        // verify a general invariant: totalSupply() must be consistent across repeated calls. That rule
        // would be too trivial. Instead, the contract intends totalSupply() to return the share token's supply.
        // We observe the share token address via c.share() and call its totalSupply() using a low-level call.
        // This is allowed because we are not re-declaring any interface; we use abi.encodeWithSignature.
        address shareAddr = c.share();
        (bool success, bytes memory data) = shareAddr.staticcall(abi.encodeWithSignature("totalSupply()"));
        require(success, "share totalSupply failed");
        uint256 shareSupply = abi.decode(data, (uint256));

        assert(supplyFromPool == shareSupply);
    }

    receive() external payable {}
}

