contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user) public {
        require(caller != address(0) && user != address(0), "zero address");

        bool callerIsWard = c.wards(caller) == 1;
        uint256 userWardsBefore = c.wards(user);
        bool reverted;

        if (caller == address(this)) {
            c.rely(user);
            reverted = false;
        } else {
            // cannot impersonate caller; only msg.sender can be used, so if caller is not this test
            // we exercise the non-authorized path by having this test call rely when it is not a ward.
            if (callerIsWard) {
                c.rely(user);
                reverted = false;
            } else {
                try c.rely(user) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        uint256 userWardsAfter = c.wards(user);

        if (!reverted) {
            assert(userWardsAfter == 1);
        } else {
            assert(userWardsAfter == userWardsBefore);
        }
    }
}

